//
// Colour bitmap glyphs from MaulBitmap.ttf and MaulSbix.ttf (generated by
// make_bitmap_font.py and make_sbix_font.py, which describe their
// glyphs): a font without outlines, every CBLC index format and CBDT
// image format, two strikes; and an sbix font with outlines, placing its
// graphics by them. Glyphs drawn at their strike's size match its pixels;
// others are scaled, the strike chosen as the smallest reaching the size.
// A PNG claiming 16384 by 16384 pixels is refused before memory is asked
// for it. Then both fonts damaged at random, their glyphs drawn or refused without
// harm under the sanitizers; the seed is fixed, so a failure repeats.

#include "test_harness.h"

#include "maul-ui/font.h"
#include "maul-ui/glyph_image.h"
#include "maul-ui/text_block.h"

#include <stdalign.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

#include "bitmap.inc"
#include "sbix.inc"

enum
{
    GLYPHS = 16,
    DAMAGE_ROUNDS = 400
};

static unsigned char s_pixels[1 << 16];
static unsigned char s_font[sizeof s_bitmap > sizeof s_sbix ? sizeof s_bitmap : sizeof s_sbix];

typedef struct Scene
{
    muiTextService* service;
    uint64_t font;
} Scene;

static bool MakeScene(Scene* scene, const unsigned char* data, size_t size)
{
    *scene = (Scene){0};
    muiTextServiceDef def = muiDefaultTextServiceDef();
    muiFontDef font = muiDefaultFontDef();
    font.data = data;
    font.size = size;
    font.dataMode = mui_fontDataBorrow;
    muiFontId id = {0, 0};
    if (muiCreateTextService(&def, &scene->service) != mui_success ||
        muiCreateFont(scene->service, &font, &id) != mui_success)
    {
        return false;
    }
    scene->font = muiFont_GetKey(id);
    return true;
}

static muiResult Draw(const Scene* scene, uint32_t glyph, float size, float offset,
                      muiGlyphImage* image)
{
    const muiLinearColor green = {0.0f, 1.0f, 0.0f, 1.0f};
    return muiTextService_RenderColorGlyph(scene->service, scene->font, glyph, size, offset, 0,
                                           green, image, s_pixels, sizeof s_pixels);
}

// Whether a glyph draws at a size into this box, left and top, width and
// height.
static bool BoxIs(const Scene* scene, uint32_t glyph, float size, float offset, int32_t left,
                  int32_t top, uint32_t width, uint32_t height, muiGlyphImage* image)
{
    return Draw(scene, glyph, size, offset, image) == mui_success && image->left == left &&
           image->top == top && image->width == width && image->height == height;
}

// Whether the pixel at x, y (y up, from the image's place) is these bytes.
static bool Is(const muiGlyphImage* image, int32_t x, int32_t y, int r, int g, int b, int a)
{
    uint32_t column = (uint32_t)(x - image->left);
    uint32_t row = (uint32_t)(image->top - 1 - y);
    const unsigned char* p = &s_pixels[((size_t)row * image->width + column) * 4];
    return p[0] == r && p[1] == g && p[2] == b && p[3] == a;
}

static void TestFormats(void)
{
    Scene scene;
    CHECK(MakeScene(&scene, s_bitmap, sizeof s_bitmap), "a font of bitmaps alone");
    muiGlyphImage image = {0};
    CHECK(BoxIs(&scene, 1, 10.0f, 0.0f, 1, 8, 8, 8, &image) && Is(&image, 1, 7, 255, 0, 0, 255) &&
              Is(&image, 5, 0, 0, 0, 255, 255),
          "index format 1, image format 17");
    CHECK(BoxIs(&scene, 2, 10.0f, 0.0f, 3, 5, 2, 2, &image) && Is(&image, 4, 3, 0, 255, 0, 255),
          "the next glyph of the range");
    CHECK(BoxIs(&scene, 3, 10.0f, 0.0f, 2, 4, 2, 2, &image) && Is(&image, 2, 2, 0, 0, 255, 255),
          "index format 3, image format 18");
    CHECK(BoxIs(&scene, 4, 10.0f, 0.0f, 1, 3, 2, 2, &image) && Is(&image, 1, 1, 255, 0, 0, 255) &&
              BoxIs(&scene, 5, 10.0f, 0.0f, 1, 3, 2, 2, &image) && Is(&image, 1, 1, 0, 255, 0, 255),
          "index format 2, image format 19");
    CHECK(BoxIs(&scene, 6, 10.0f, 0.0f, 0, 2, 2, 2, &image) && Is(&image, 0, 0, 0, 0, 255, 255) &&
              BoxIs(&scene, 8, 10.0f, 0.0f, 0, 2, 2, 2, &image) &&
              Is(&image, 0, 0, 255, 0, 0, 255) && Draw(&scene, 7, 10.0f, 0.0f, &image) == mui_empty,
          "index format 4, a glyph of its range without an image");
    CHECK(BoxIs(&scene, 9, 10.0f, 0.0f, 2, 2, 2, 2, &image) && Is(&image, 2, 0, 0, 255, 0, 255) &&
              BoxIs(&scene, 11, 10.0f, 0.0f, 2, 2, 2, 2, &image) &&
              Is(&image, 2, 0, 0, 0, 255, 255) &&
              Draw(&scene, 10, 10.0f, 0.0f, &image) == mui_empty,
          "index format 5, a glyph of its range without an image");
    CHECK(Draw(&scene, 13, 10.0f, 0.0f, &image) == mui_empty && image.width == 0,
          "a glyph without a bitmap is empty");
    CHECK(Draw(&scene, 14, 10.0f, 0.0f, &image) == mui_empty,
          "a PNG longer than its image is refused");
    // Red at half alpha: linear red 0.502 premultiplied, 188 encoded.
    CHECK(BoxIs(&scene, 15, 10.0f, 0.0f, 0, 2, 2, 2, &image) && Is(&image, 0, 0, 188, 0, 0, 128),
          "straight alpha made premultiplied");
    CHECK(muiTextService_RenderGlyph(scene.service, scene.font, 1, 10.0f, 0.0f, &image, s_pixels,
                                     sizeof s_pixels) == mui_success &&
              image.width == 0,
          "no coverage in a font without outlines");
    muiDestroyTextService(scene.service);
}

static void TestScaling(void)
{
    Scene scene;
    CHECK(MakeScene(&scene, s_bitmap, sizeof s_bitmap), "the font");
    muiGlyphImage image = {0};
    // 20 ppem's glyph 1 is green on its right, 10 ppem's blue.
    CHECK(BoxIs(&scene, 1, 20.0f, 0.0f, 2, 16, 16, 16, &image) && Is(&image, 12, 8, 0, 255, 0, 255),
          "the strike of the size itself");
    // The 15 ppem strike is not colour: 20 is the smallest that reaches.
    CHECK(BoxIs(&scene, 1, 15.0f, 0.0f, 1, 12, 13, 12, &image) &&
              Is(&image, 10, 6, 0, 255, 0, 255) && Is(&image, 3, 6, 255, 0, 0, 255),
          "the smallest colour strike reaching the size, shrunk");
    CHECK(Draw(&scene, 1, 5.0f, 0.0f, &image) == mui_success && Is(&image, 3, 1, 0, 0, 255, 255),
          "the smallest strike of all for a smaller size");
    CHECK(Draw(&scene, 1, 30.0f, 0.0f, &image) == mui_success && image.width == 24 &&
              Is(&image, 20, 10, 0, 255, 0, 255),
          "the largest strike, grown, for a larger size");
    // Glyph 12 is only in the 20 ppem strike: its top row of four red,
    // halved, makes a top row half red.
    CHECK(BoxIs(&scene, 12, 10.0f, 0.0f, 0, 2, 2, 2, &image) && Is(&image, 0, 1, 188, 0, 0, 128) &&
              Is(&image, 1, 0, 0, 0, 0, 0),
          "a strike without the glyph passed over, the image averaged");
    // Half a pixel right: the first column half red.
    CHECK(BoxIs(&scene, 1, 10.0f, 0.5f, 1, 8, 9, 8, &image) && Is(&image, 1, 7, 188, 0, 0, 128) &&
              Is(&image, 2, 7, 255, 0, 0, 255),
          "an offset pen");
    muiDestroyTextService(scene.service);
}

static void TestSbix(void)
{
    Scene scene;
    CHECK(MakeScene(&scene, s_sbix, sizeof s_sbix), "an sbix font");
    muiGlyphImage image = {0};
    // Its outline box's lower left corner, 1 and -1 pixels at 10 ppem,
    // moves it.
    CHECK(BoxIs(&scene, 1, 10.0f, 0.0f, 2, 3, 4, 4, &image) && Is(&image, 2, -1, 255, 0, 0, 255),
          "a graphic placed from its outline's box");
    CHECK(BoxIs(&scene, 1, 20.0f, 0.0f, 4, 6, 8, 8, &image) && Is(&image, 4, -2, 0, 255, 0, 255),
          "the strike of the size, though later in the table");
    CHECK(BoxIs(&scene, 1, 15.0f, 0.0f, 3, 5, 6, 7, &image) && Is(&image, 5, 1, 0, 255, 0, 255),
          "the smallest strike reaching the size, shrunk");
    CHECK(BoxIs(&scene, 2, 10.0f, 0.0f, 1, 4, 2, 2, &image) && Is(&image, 1, 2, 0, 0, 255, 255),
          "a graphic placed from the pen without an outline");
    CHECK(BoxIs(&scene, 3, 10.0f, 0.0f, 1, 4, 2, 2, &image) && Is(&image, 2, 3, 0, 0, 255, 255),
          "a dupe drawn as the glyph it names");
    CHECK(Draw(&scene, 4, 10.0f, 0.0f, &image) == mui_empty, "a JPEG graphic not drawn");
    CHECK(Draw(&scene, 5, 10.0f, 0.0f, &image) == mui_empty, "a dupe of itself not drawn");
    CHECK(Draw(&scene, 7, 10.0f, 0.0f, &image) == mui_empty,
          "a PNG called a JPEG not drawn: the graphic's type rules");
    // 1.5 pixels in: the first column half red.
    CHECK(BoxIs(&scene, 6, 10.0f, 0.0f, 1, 2, 3, 2, &image) && Is(&image, 1, 1, 188, 0, 0, 128) &&
              Is(&image, 2, 1, 255, 0, 0, 255),
          "an outline's box a fraction of a pixel in");
    // FreeType would take the font for one of bitmaps alone; its outlines
    // still draw as coverage, 1 to 5 across and -1 to 3 up.
    CHECK(muiTextService_RenderGlyph(scene.service, scene.font, 1, 10.0f, 0.0f, &image, s_pixels,
                                     sizeof s_pixels) == mui_success &&
              image.left == 1 && image.top == 3 && image.width == 4 && image.height == 4,
          "an sbix font's outlines as coverage");
    muiDestroyTextService(scene.service);
}

// An allocator that refuses more than 64 MiB at once and keeps the
// largest size asked for.
static size_t s_largest;

static void* BoundedAlloc(size_t size, size_t alignment, void* context)
{
    (void)context;
    s_largest = size > s_largest ? size : s_largest;
    return size <= ((size_t)64 << 20) && alignment <= alignof(max_align_t) ? malloc(size) : NULL;
}

static void BoundedFree(void* memory, size_t size, size_t alignment, void* context)
{
    (void)size;
    (void)alignment;
    (void)context;
    free(memory);
}

static uint32_t Crc32(const unsigned char* data, size_t size)
{
    uint32_t crc = 0xFFFFFFFFu;
    for (size_t i = 0; i < size; i++)
    {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++)
        {
            crc = (crc >> 1) ^ (0xEDB88320u & (0u - (crc & 1u)));
        }
    }
    return ~crc;
}

static void PutBig32(unsigned char* p, uint32_t value)
{
    p[0] = (unsigned char)(value >> 24);
    p[1] = (unsigned char)(value >> 16);
    p[2] = (unsigned char)(value >> 8);
    p[3] = (unsigned char)value;
}

// A copy of MaulSbix.ttf whose first PNG, glyph 1's at 20 pixels, says
// it is 16384 by 16384, its header's checksum made again: 2^28 pixels,
// whose 16 bytes each in linear light are 2^32 and wrapped to 0 where a
// size_t is 32 bits. Refused as malformed on every platform, before the
// service asks for memory for it.
static void TestOversizedBitmap(void)
{
    memcpy(s_font, s_sbix, sizeof s_sbix);
    size_t header = 0;
    for (size_t at = 4; at + 21 <= sizeof s_sbix && header == 0; at++)
    {
        header = memcmp(s_font + at, "IHDR", 4) == 0 ? at : 0;
    }
    CHECK(header != 0 && s_font[header - 1] == 13 && s_font[header + 7] == 8,
          "glyph 1's PNG header, 8 pixels wide");
    PutBig32(s_font + header + 4, 16384);
    PutBig32(s_font + header + 8, 16384);
    PutBig32(s_font + header + 17, Crc32(s_font + header, 17));
    muiTextServiceDef def = muiDefaultTextServiceDef();
    def.allocator = (muiAllocator){BoundedAlloc, BoundedFree, NULL};
    muiFontDef fontDef = muiDefaultFontDef();
    fontDef.data = s_font;
    fontDef.size = sizeof s_sbix;
    fontDef.dataMode = mui_fontDataBorrow;
    muiFontId id = {0, 0};
    Scene scene = {0};
    CHECK(muiCreateTextService(&def, &scene.service) == mui_success &&
              muiCreateFont(scene.service, &fontDef, &id) == mui_success,
          "a PNG of 16384 by 16384 pixels");
    scene.font = muiFont_GetKey(id);
    s_largest = 0;
    muiGlyphImage image = {0};
    CHECK(Draw(&scene, 1, 20.0f, 0.0f, &image) == mui_errorFormat && image.width == 0,
          "refused as malformed");
    CHECK(s_largest < ((size_t)1 << 20), "without asking for its pixels' memory");
    CHECK(BoxIs(&scene, 2, 10.0f, 0.0f, 1, 4, 2, 2, &image), "the font's other glyphs drawn");
    muiDestroyTextService(scene.service);
}

static uint32_t Next(uint32_t* state)
{
    *state ^= *state << 13;
    *state ^= *state >> 17;
    *state ^= *state << 5;
    return *state;
}

// Damages a font at random, round after round, drawing every glyph of
// those still made; how many were.
static uint32_t Damage(const unsigned char* font, size_t size, uint32_t state)
{
    uint32_t made = 0;
    for (uint32_t round = 0; round < DAMAGE_ROUNDS; round++)
    {
        memcpy(s_font, font, size);
        uint32_t flips = 1 + Next(&state) % 8;
        for (uint32_t i = 0; i < flips; i++)
        {
            s_font[Next(&state) % size] ^= (unsigned char)(1u << (Next(&state) % 8));
        }
        Scene scene;
        if (MakeScene(&scene, s_font, size))
        {
            made++;
            for (uint32_t glyph = 0; glyph < GLYPHS; glyph++)
            {
                muiGlyphImage image = {0};
                (void)Draw(&scene, glyph, 7.0f + (float)(glyph % 4) * 6.0f, 0.25f, &image);
            }
        }
        muiDestroyTextService(scene.service);
    }
    return made;
}

static void TestDamage(void)
{
    CHECK(Damage(s_bitmap, sizeof s_bitmap, 0x2545F491u) > DAMAGE_ROUNDS / 4 &&
              Damage(s_sbix, sizeof s_sbix, 0x9E3779B9u) > DAMAGE_ROUNDS / 4,
          "damaged fonts made and drawn or refused");
}

// An image's bytes, four a pixel, as an FNV-1a hash.
static uint32_t Hash(const muiGlyphImage* image)
{
    uint32_t hash = 2166136261u;
    for (size_t i = 0; i < (size_t)image->width * image->height * 4; i++)
    {
        hash = (hash ^ s_pixels[i]) * 16777619u;
    }
    return hash;
}

// A rendering's result with its image: the hash, or the status for none.
static uint32_t Outcome(muiResult result, const muiGlyphImage* image)
{
    return result == mui_success ? Hash(image) : (uint32_t)result;
}

// Every bitmap glyph whole: CBDT strikes at, below, between and above
// their sizes and at a pen half a pixel on, and sbix's; the same bytes on
// every platform.
static void TestWholeImages(void)
{
    static const uint32_t expected[16] = {0x1b305de5u, 0x3638be45u, 0xe2296f15u, 0x9eba52c5u,
                                          0x23ccbe19u, 0xca6dca85u, 0x5a17b5a5u, 0x4ab8dbffu,
                                          0x9c7559a5u, 0xe21bb2b5u, 0x904a5fc5u, 0x50c0069du,
                                          0x50c0069du, 0x10abb889u, 0x5f035bc6u, 0xa5c32621u};
    const struct
    {
        bool sbix;
        uint32_t glyph;
        float size;
        float offset;
    } draws[16] = {{false, 1, 5.0f, 0.0f},   {false, 1, 10.0f, 0.0f},  {false, 1, 15.0f, 0.0f},
                   {false, 1, 20.0f, 0.0f},  {false, 1, 30.0f, 0.0f},  {false, 1, 10.0f, 0.5f},
                   {false, 12, 10.0f, 0.0f}, {false, 1, 41.0f, 0.25f}, {true, 1, 10.0f, 0.0f},
                   {true, 1, 15.0f, 0.0f},   {true, 1, 20.0f, 0.0f},   {true, 2, 10.0f, 0.0f},
                   {true, 3, 10.0f, 0.0f},   {true, 6, 10.0f, 0.0f},   {true, 1, 33.0f, 0.5f},
                   {true, 6, 7.0f, 0.25f}};
    Scene bitmap;
    Scene sbix;
    CHECK(MakeScene(&bitmap, s_bitmap, sizeof s_bitmap) && MakeScene(&sbix, s_sbix, sizeof s_sbix),
          "both fonts");
    uint32_t got[16];
    for (uint32_t i = 0; i < 16; i++)
    {
        muiGlyphImage image = {0};
        muiResult result = Draw(draws[i].sbix ? &sbix : &bitmap, draws[i].glyph, draws[i].size,
                                draws[i].offset, &image);
        got[i] = Outcome(result, &image);
    }
    bool held = true;
    for (uint32_t i = 0; i < 16; i++)
    {
        held = held && got[i] == expected[i];
    }
    CHECK(held, "every bitmap glyph's bytes, as on every platform");
    muiDestroyTextService(bitmap.service);
    muiDestroyTextService(sbix.service);
}

int main(void)
{
    TestFormats();
    TestScaling();
    TestWholeImages();
    TestSbix();
    TestOversizedBitmap();
    TestDamage();
    return s_failures == 0 ? 0 : 1;
}
